contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount, uint256 outgoing) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 cBalanceBefore = address(c).balance;
        uint256 balanceBefore = address(this).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        c.withdraw(amount); if (__ESBMC_reverted()) return;

        assert(address(c).balance == cBalanceBefore && address(this).balance == balanceBefore);
    }
}

