// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 amount, uint256 outgoing) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 cBalanceBefore = address(c).balance;
        uint256 balanceBefore = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        try c.withdraw(amount) {} catch { return; }
        assertTrue(address(c).balance == cBalanceBefore && address(this).balance == balanceBefore);
    }

    function testFuzz_run(uint256 amount, uint256 outgoing) public {
        _run(amount, outgoing);
    }

    receive() external payable {}
}
